import React from 'react';

import {
  OverlaysProps,
  OverlayHandlers,
} from '../../../../core/types/overlays.js';
import { usePinnedState, useSetState } from '../../../hooks/store/selectors.js';

export const useCategoricalMouseEventHandlers = (): OverlayHandlers => {
  const { pinned } = usePinnedState();
  const setState = useSetState();

  const mouseMoveHandler = (
    event: React.MouseEvent,
    overlaysState: OverlaysProps,
  ) => {
    if (!pinned) {
      setState((prev) => ({
        ...prev,
        pinned: {
          ...prev.pinned,
          visible: overlaysState.isInChartBounds || prev.pinned.pinned,
        },
      }));
    }
  };

  const mouseLeave = () => {
    setState((prev) => ({
      ...prev,
      pinned: {
        ...prev.pinned,
        visible: prev.pinned.pinned,
      },
    }));
  };

  return {
    move: mouseMoveHandler,
    leave: mouseLeave,
  };
};
